    this.email,
    required this.fiscalYearStartMonth,
    required this.baseCurrency,
    required this.roundingMode,
    required this.roundInvoiceToRupee,
    required this.pricesIncludeTax,
    this.raastAlias,
    this.bankName,
    this.bankAccountTitle,
    this.bankIban,
  });
