class Device extends DataClass implements Insertable<Device> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;

  /// Bootstrap root; see the note on `firms` above. A device is registered
  /// during first run, before the owner's user row exists.
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String label;
  final String deviceRole;
  final String platform;
  final String? model;
  final String? osVersion;
  final String? appVersion;

  /// Per-device document number prefix. Two cashiers must never mint the same
  /// invoice number, and renumbering after the fact is not an option.
  final String docPrefix;
  final int isThisDevice;
  final int? lastSeenAtUtc;

  /// Monotonic counter feeding change_log.seq. Never reset, never derived from
  /// a wall clock.
  final int changeSeq;
  const Device({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.label,
    required this.deviceRole,
    required this.platform,
    this.model,
    this.osVersion,
    this.appVersion,
    required this.docPrefix,
    required this.isThisDevice,
    this.lastSeenAtUtc,
    required this.changeSeq,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['label'] = Variable<String>(label);
    map['device_role'] = Variable<String>(deviceRole);
    map['platform'] = Variable<String>(platform);
    if (!nullToAbsent || model != null) {
      map['model'] = Variable<String>(model);
    }
    if (!nullToAbsent || osVersion != null) {
      map['os_version'] = Variable<String>(osVersion);
    }
    if (!nullToAbsent || appVersion != null) {
      map['app_version'] = Variable<String>(appVersion);
    }
    map['doc_prefix'] = Variable<String>(docPrefix);
    map['is_this_device'] = Variable<int>(isThisDevice);
    if (!nullToAbsent || lastSeenAtUtc != null) {
      map['last_seen_at_utc'] = Variable<int>(lastSeenAtUtc);
    }
    map['change_seq'] = Variable<int>(changeSeq);
    return map;
  }

  DevicesCompanion toCompanion(bool nullToAbsent) {
    return DevicesCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAtUtc),
      originDeviceId: Value(originDeviceId),
      hlc: Value(hlc),
      rev: Value(rev),
      label: Value(label),
      deviceRole: Value(deviceRole),
      platform: Value(platform),
      model: model == null && nullToAbsent
          ? const Value.absent()
          : Value(model),
      osVersion: osVersion == null && nullToAbsent
          ? const Value.absent()
          : Value(osVersion),
      appVersion: appVersion == null && nullToAbsent
          ? const Value.absent()
          : Value(appVersion),
      docPrefix: Value(docPrefix),
      isThisDevice: Value(isThisDevice),
      lastSeenAtUtc: lastSeenAtUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(lastSeenAtUtc),
      changeSeq: Value(changeSeq),
    );
  }

  factory Device.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Device(
      id: serializer.fromJson<String>(json['id']),
      firmId: serializer.fromJson<String>(json['firm_id']),
      createdAtUtc: serializer.fromJson<int>(json['created_at_utc']),
      updatedAtUtc: serializer.fromJson<int>(json['updated_at_utc']),
      createdBy: serializer.fromJson<String>(json['created_by']),
      updatedBy: serializer.fromJson<String>(json['updated_by']),
      deletedAtUtc: serializer.fromJson<int?>(json['deleted_at_utc']),
      originDeviceId: serializer.fromJson<String>(json['origin_device_id']),
      hlc: serializer.fromJson<String>(json['hlc']),
      rev: serializer.fromJson<int>(json['rev']),
      label: serializer.fromJson<String>(json['label']),
      deviceRole: serializer.fromJson<String>(json['device_role']),
      platform: serializer.fromJson<String>(json['platform']),
      model: serializer.fromJson<String?>(json['model']),
      osVersion: serializer.fromJson<String?>(json['os_version']),
      appVersion: serializer.fromJson<String?>(json['app_version']),
      docPrefix: serializer.fromJson<String>(json['doc_prefix']),
      isThisDevice: serializer.fromJson<int>(json['is_this_device']),
      lastSeenAtUtc: serializer.fromJson<int?>(json['last_seen_at_utc']),
      changeSeq: serializer.fromJson<int>(json['change_seq']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'firm_id': serializer.toJson<String>(firmId),
      'created_at_utc': serializer.toJson<int>(createdAtUtc),
      'updated_at_utc': serializer.toJson<int>(updatedAtUtc),
      'created_by': serializer.toJson<String>(createdBy),
      'updated_by': serializer.toJson<String>(updatedBy),
      'deleted_at_utc': serializer.toJson<int?>(deletedAtUtc),
      'origin_device_id': serializer.toJson<String>(originDeviceId),
      'hlc': serializer.toJson<String>(hlc),
      'rev': serializer.toJson<int>(rev),
      'label': serializer.toJson<String>(label),
      'device_role': serializer.toJson<String>(deviceRole),
      'platform': serializer.toJson<String>(platform),
      'model': serializer.toJson<String?>(model),
      'os_version': serializer.toJson<String?>(osVersion),
      'app_version': serializer.toJson<String?>(appVersion),
      'doc_prefix': serializer.toJson<String>(docPrefix),
      'is_this_device': serializer.toJson<int>(isThisDevice),
      'last_seen_at_utc': serializer.toJson<int?>(lastSeenAtUtc),
      'change_seq': serializer.toJson<int>(changeSeq),
    };
  }

  Device copyWith({
    String? id,
    String? firmId,
    int? createdAtUtc,
    int? updatedAtUtc,
    String? createdBy,
    String? updatedBy,
    Value<int?> deletedAtUtc = const Value.absent(),
    String? originDeviceId,
    String? hlc,
    int? rev,
    String? label,
    String? deviceRole,
    String? platform,
    Value<String?> model = const Value.absent(),
    Value<String?> osVersion = const Value.absent(),
    Value<String?> appVersion = const Value.absent(),
    String? docPrefix,
    int? isThisDevice,
    Value<int?> lastSeenAtUtc = const Value.absent(),
    int? changeSeq,
  }) => Device(
    id: id ?? this.id,
    firmId: firmId ?? this.firmId,
    createdAtUtc: createdAtUtc ?? this.createdAtUtc,
    updatedAtUtc: updatedAtUtc ?? this.updatedAtUtc,
    createdBy: createdBy ?? this.createdBy,
    updatedBy: updatedBy ?? this.updatedBy,
    deletedAtUtc: deletedAtUtc.present ? deletedAtUtc.value : this.deletedAtUtc,
    originDeviceId: originDeviceId ?? this.originDeviceId,
    hlc: hlc ?? this.hlc,
    rev: rev ?? this.rev,
    label: label ?? this.label,
    deviceRole: deviceRole ?? this.deviceRole,
    platform: platform ?? this.platform,
    model: model.present ? model.value : this.model,
    osVersion: osVersion.present ? osVersion.value : this.osVersion,
    appVersion: appVersion.present ? appVersion.value : this.appVersion,
    docPrefix: docPrefix ?? this.docPrefix,
    isThisDevice: isThisDevice ?? this.isThisDevice,
    lastSeenAtUtc: lastSeenAtUtc.present
        ? lastSeenAtUtc.value
        : this.lastSeenAtUtc,
    changeSeq: changeSeq ?? this.changeSeq,
  );
  Device copyWithCompanion(DevicesCompanion data) {
    return Device(
      id: data.id.present ? data.id.value : this.id,
      firmId: data.firmId.present ? data.firmId.value : this.firmId,
      createdAtUtc: data.createdAtUtc.present
          ? data.createdAtUtc.value
          : this.createdAtUtc,
      updatedAtUtc: data.updatedAtUtc.present
          ? data.updatedAtUtc.value
          : this.updatedAtUtc,
      createdBy: data.createdBy.present ? data.createdBy.value : this.createdBy,
      updatedBy: data.updatedBy.present ? data.updatedBy.value : this.updatedBy,
      deletedAtUtc: data.deletedAtUtc.present
          ? data.deletedAtUtc.value
          : this.deletedAtUtc,
      originDeviceId: data.originDeviceId.present
          ? data.originDeviceId.value
          : this.originDeviceId,
      hlc: data.hlc.present ? data.hlc.value : this.hlc,
      rev: data.rev.present ? data.rev.value : this.rev,
      label: data.label.present ? data.label.value : this.label,
      deviceRole: data.deviceRole.present
          ? data.deviceRole.value
          : this.deviceRole,
      platform: data.platform.present ? data.platform.value : this.platform,
      model: data.model.present ? data.model.value : this.model,
      osVersion: data.osVersion.present ? data.osVersion.value : this.osVersion,
      appVersion: data.appVersion.present
          ? data.appVersion.value
          : this.appVersion,
      docPrefix: data.docPrefix.present ? data.docPrefix.value : this.docPrefix,
      isThisDevice: data.isThisDevice.present
          ? data.isThisDevice.value
          : this.isThisDevice,
      lastSeenAtUtc: data.lastSeenAtUtc.present
          ? data.lastSeenAtUtc.value
          : this.lastSeenAtUtc,
      changeSeq: data.changeSeq.present ? data.changeSeq.value : this.changeSeq,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Device(')
          ..write('id: $id, ')
          ..write('firmId: $firmId, ')
          ..write('createdAtUtc: $createdAtUtc, ')
          ..write('updatedAtUtc: $updatedAtUtc, ')
          ..write('createdBy: $createdBy, ')
          ..write('updatedBy: $updatedBy, ')
          ..write('deletedAtUtc: $deletedAtUtc, ')
