class User extends DataClass implements Insertable<User> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String name;
  final String role;
  final String? phone;

  /// Argon2id. Never a plaintext or reversible PIN.
  final String? pinHash;
  final String? pinSalt;
  final int biometricEnabled;

  /// M9 populates these from the role. The columns exist now so ActorContext
  /// has somewhere to read from without a later migration touching 300 call
  /// sites.
  final int canSeePurchasePrice;
  final int canSeeMargin;
  final int maxDiscountBp;
  final int isActive;
  final int? lastLoginAtUtc;
  const User({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.name,
    required this.role,
    this.phone,
    this.pinHash,
    this.pinSalt,
    required this.biometricEnabled,
    required this.canSeePurchasePrice,
    required this.canSeeMargin,
    required this.maxDiscountBp,
    required this.isActive,
    this.lastLoginAtUtc,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['name'] = Variable<String>(name);
    map['role'] = Variable<String>(role);
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || pinHash != null) {
      map['pin_hash'] = Variable<String>(pinHash);
    }
    if (!nullToAbsent || pinSalt != null) {
      map['pin_salt'] = Variable<String>(pinSalt);
    }
    map['biometric_enabled'] = Variable<int>(biometricEnabled);
    map['can_see_purchase_price'] = Variable<int>(canSeePurchasePrice);
    map['can_see_margin'] = Variable<int>(canSeeMargin);
    map['max_discount_bp'] = Variable<int>(maxDiscountBp);
    map['is_active'] = Variable<int>(isActive);
    if (!nullToAbsent || lastLoginAtUtc != null) {
      map['last_login_at_utc'] = Variable<int>(lastLoginAtUtc);
    }
    return map;
  }

  UsersCompanion toCompanion(bool nullToAbsent) {
    return UsersCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
