class TaxRule extends DataClass implements Insertable<TaxRule> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String packVersion;
  final String code;
  final String nameEn;
  final String nameUr;
  final String taxKind;
  final String jurisdiction;

  /// Basis points. The 8th Schedule's real slabs include 8.5%, 12.5% and
  /// 12.75%, none of which survive an integer percent and none of which should
  /// ever become a float.
  final int rateBp;
  final String appliesTo;
  final String effectiveFromLocal;
  final String? effectiveToLocal;

  /// Further tax under s.3(1A) STA is 4% and is triggered by the buyer being
  /// off the Active Taxpayer List. This flag is what the posting rule tests.
  final int requiresBuyerOffAtl;

  /// 3rd Schedule goods are taxed on printed retail price, not on the sale
  /// value, which changes the base and not just the rate.
  final int taxesOnMrp;
  final String? sroScheduleNo;
  final String? sroItemNo;
  final String? statuteRef;

  /// 0 for a rule the shopkeeper added by hand.
  final int isSystem;
  final int isActive;
  const TaxRule({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.packVersion,
    required this.code,
    required this.nameEn,
    required this.nameUr,
    required this.taxKind,
    required this.jurisdiction,
    required this.rateBp,
    required this.appliesTo,
    required this.effectiveFromLocal,
    this.effectiveToLocal,
    required this.requiresBuyerOffAtl,
    required this.taxesOnMrp,
    this.sroScheduleNo,
    this.sroItemNo,
    this.statuteRef,
    required this.isSystem,
    required this.isActive,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['pack_version'] = Variable<String>(packVersion);
    map['code'] = Variable<String>(code);
    map['name_en'] = Variable<String>(nameEn);
    map['name_ur'] = Variable<String>(nameUr);
    map['tax_kind'] = Variable<String>(taxKind);
    map['jurisdiction'] = Variable<String>(jurisdiction);
    map['rate_bp'] = Variable<int>(rateBp);
    map['applies_to'] = Variable<String>(appliesTo);
    map['effective_from_local'] = Variable<String>(effectiveFromLocal);
    if (!nullToAbsent || effectiveToLocal != null) {
      map['effective_to_local'] = Variable<String>(effectiveToLocal);
    }
    map['requires_buyer_off_atl'] = Variable<int>(requiresBuyerOffAtl);
    map['taxes_on_mrp'] = Variable<int>(taxesOnMrp);
    if (!nullToAbsent || sroScheduleNo != null) {
      map['sro_schedule_no'] = Variable<String>(sroScheduleNo);
    }
    if (!nullToAbsent || sroItemNo != null) {
      map['sro_item_no'] = Variable<String>(sroItemNo);
    }
    if (!nullToAbsent || statuteRef != null) {
      map['statute_ref'] = Variable<String>(statuteRef);
    }
    map['is_system'] = Variable<int>(isSystem);
    map['is_active'] = Variable<int>(isActive);
    return map;
  }

  TaxRulesCompanion toCompanion(bool nullToAbsent) {
    return TaxRulesCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAtUtc),
      originDeviceId: Value(originDeviceId),
      hlc: Value(hlc),
      rev: Value(rev),
      packVersion: Value(packVersion),
      code: Value(code),
      nameEn: Value(nameEn),
      nameUr: Value(nameUr),
      taxKind: Value(taxKind),
      jurisdiction: Value(jurisdiction),
      rateBp: Value(rateBp),
      appliesTo: Value(appliesTo),
      effectiveFromLocal: Value(effectiveFromLocal),
      effectiveToLocal: effectiveToLocal == null && nullToAbsent
          ? const Value.absent()
          : Value(effectiveToLocal),
      requiresBuyerOffAtl: Value(requiresBuyerOffAtl),
      taxesOnMrp: Value(taxesOnMrp),
      sroScheduleNo: sroScheduleNo == null && nullToAbsent
          ? const Value.absent()
          : Value(sroScheduleNo),
      sroItemNo: sroItemNo == null && nullToAbsent
          ? const Value.absent()
          : Value(sroItemNo),
      statuteRef: statuteRef == null && nullToAbsent
          ? const Value.absent()
          : Value(statuteRef),
      isSystem: Value(isSystem),
      isActive: Value(isActive),
    );
  }

  factory TaxRule.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return TaxRule(
      id: serializer.fromJson<String>(json['id']),
      firmId: serializer.fromJson<String>(json['firm_id']),
      createdAtUtc: serializer.fromJson<int>(json['created_at_utc']),
      updatedAtUtc: serializer.fromJson<int>(json['updated_at_utc']),
      createdBy: serializer.fromJson<String>(json['created_by']),
      updatedBy: serializer.fromJson<String>(json['updated_by']),
      deletedAtUtc: serializer.fromJson<int?>(json['deleted_at_utc']),
      originDeviceId: serializer.fromJson<String>(json['origin_device_id']),
