          ..write('effectiveToLocal: $effectiveToLocal, ')
          ..write('requiresBuyerOffAtl: $requiresBuyerOffAtl, ')
          ..write('taxesOnMrp: $taxesOnMrp, ')
          ..write('sroScheduleNo: $sroScheduleNo, ')
          ..write('sroItemNo: $sroItemNo, ')
          ..write('statuteRef: $statuteRef, ')
          ..write('isSystem: $isSystem, ')
          ..write('isActive: $isActive, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

