class Attachment extends DataClass implements Insertable<Attachment> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String kind;

  /// A loose back-reference on purpose: an attachment outlives the row that
  /// pointed at it, and a hard FK here would need one column per owner table.
  final String? ownerTable;
  final String? ownerId;
  final String fileName;
  final String mimeType;
  final int byteSize;
  final String sha256;

  /// Small images live inline so a backup is one file and a restore cannot
  /// come back with missing pictures. Anything larger goes to storage_path.
  final Uint8List? bytes;
  final String? storagePath;
  final int? width;
  final int? height;
  const Attachment({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.kind,
    this.ownerTable,
    this.ownerId,
    required this.fileName,
    required this.mimeType,
    required this.byteSize,
    required this.sha256,
    this.bytes,
    this.storagePath,
    this.width,
    this.height,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['kind'] = Variable<String>(kind);
    if (!nullToAbsent || ownerTable != null) {
      map['owner_table'] = Variable<String>(ownerTable);
    }
    if (!nullToAbsent || ownerId != null) {
      map['owner_id'] = Variable<String>(ownerId);
    }
    map['file_name'] = Variable<String>(fileName);
    map['mime_type'] = Variable<String>(mimeType);
    map['byte_size'] = Variable<int>(byteSize);
    map['sha256'] = Variable<String>(sha256);
    if (!nullToAbsent || bytes != null) {
      map['bytes'] = Variable<Uint8List>(bytes);
    }
    if (!nullToAbsent || storagePath != null) {
      map['storage_path'] = Variable<String>(storagePath);
    }
    if (!nullToAbsent || width != null) {
      map['width'] = Variable<int>(width);
    }
    if (!nullToAbsent || height != null) {
      map['height'] = Variable<int>(height);
    }
    return map;
  }

  AttachmentsCompanion toCompanion(bool nullToAbsent) {
    return AttachmentsCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAtUtc),
      originDeviceId: Value(originDeviceId),
      hlc: Value(hlc),
      rev: Value(rev),
      kind: Value(kind),
      ownerTable: ownerTable == null && nullToAbsent
          ? const Value.absent()
          : Value(ownerTable),
      ownerId: ownerId == null && nullToAbsent
          ? const Value.absent()
          : Value(ownerId),
      fileName: Value(fileName),
      mimeType: Value(mimeType),
      byteSize: Value(byteSize),
      sha256: Value(sha256),
      bytes: bytes == null && nullToAbsent
          ? const Value.absent()
          : Value(bytes),
      storagePath: storagePath == null && nullToAbsent
          ? const Value.absent()
          : Value(storagePath),
      width: width == null && nullToAbsent
          ? const Value.absent()
          : Value(width),
      height: height == null && nullToAbsent
          ? const Value.absent()
          : Value(height),
    );
