class Party extends DataClass implements Insertable<Party> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String name;
  final String nameSearch;
  final String partyType;
  final String? partyGroup;
  final String? phone;
  final String? whatsapp;
  final String? email;
  final String? addressLine1;
  final String? addressLine2;
  final String? city;
  final String? province;
  final String? ntn;
  final String? strn;
  final String? cnic;

  /// FBR's own field name. 'unregistered' is the default because most buyers
  /// at a kiryana counter are.
  final String buyerRegistrationType;

  /// Further tax under s.3(1A) STA is 4% since the Finance Act 2023 and is
  /// triggered by the buyer being OFF the Active Taxpayer List — not merely by
  /// their lacking an STRN. NULL means unknown, which is not the same as false.
  final int? isOnAtl;

  /// Positive means the party owes us.
  final int openingBalancePaisa;
  final String? openingBalanceAsOfLocal;
  final int? creditLimitPaisa;
  final int? creditDays;
  final int defaultDiscountBp;
  final int isActive;

  /// Which of an item's prices this party is sold at. Added in v4: items have
  /// carried a wholesale rate since M1 and the counter charged every buyer
  /// the retail one, so a wholesaler's regular retailers were overcharged
  /// unless the cashier remembered to retype every line. Last in the table
  /// because SQLite adds a column where it adds it: at the end.
  final String priceTier;
  const Party({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.name,
    required this.nameSearch,
    required this.partyType,
    this.partyGroup,
    this.phone,
    this.whatsapp,
    this.email,
    this.addressLine1,
    this.addressLine2,
    this.city,
    this.province,
    this.ntn,
    this.strn,
    this.cnic,
    required this.buyerRegistrationType,
    this.isOnAtl,
    required this.openingBalancePaisa,
    this.openingBalanceAsOfLocal,
    this.creditLimitPaisa,
    this.creditDays,
    required this.defaultDiscountBp,
    required this.isActive,
    required this.priceTier,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['name'] = Variable<String>(name);
    map['name_search'] = Variable<String>(nameSearch);
    map['party_type'] = Variable<String>(partyType);
    if (!nullToAbsent || partyGroup != null) {
      map['party_group'] = Variable<String>(partyGroup);
    }
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || whatsapp != null) {
      map['whatsapp'] = Variable<String>(whatsapp);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || addressLine1 != null) {
      map['address_line1'] = Variable<String>(addressLine1);
    }
    if (!nullToAbsent || addressLine2 != null) {
      map['address_line2'] = Variable<String>(addressLine2);
    }
    if (!nullToAbsent || city != null) {
      map['city'] = Variable<String>(city);
    }
    if (!nullToAbsent || province != null) {
      map['province'] = Variable<String>(province);
    }
    if (!nullToAbsent || ntn != null) {
      map['ntn'] = Variable<String>(ntn);
    }
    if (!nullToAbsent || strn != null) {
      map['strn'] = Variable<String>(strn);
    }
    if (!nullToAbsent || cnic != null) {
      map['cnic'] = Variable<String>(cnic);
    }
    map['buyer_registration_type'] = Variable<String>(buyerRegistrationType);
    if (!nullToAbsent || isOnAtl != null) {
      map['is_on_atl'] = Variable<int>(isOnAtl);
    }
    map['opening_balance_paisa'] = Variable<int>(openingBalancePaisa);
    if (!nullToAbsent || openingBalanceAsOfLocal != null) {
      map['opening_balance_as_of_local'] = Variable<String>(
        openingBalanceAsOfLocal,
      );
    }
    if (!nullToAbsent || creditLimitPaisa != null) {
      map['credit_limit_paisa'] = Variable<int>(creditLimitPaisa);
    }
    if (!nullToAbsent || creditDays != null) {
      map['credit_days'] = Variable<int>(creditDays);
    }
    map['default_discount_bp'] = Variable<int>(defaultDiscountBp);
    map['is_active'] = Variable<int>(isActive);
    map['price_tier'] = Variable<String>(priceTier);
    return map;
  }

  PartiesCompanion toCompanion(bool nullToAbsent) {
    return PartiesCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAtUtc),
      originDeviceId: Value(originDeviceId),
      hlc: Value(hlc),
      rev: Value(rev),
      name: Value(name),
      nameSearch: Value(nameSearch),
      partyType: Value(partyType),
      partyGroup: partyGroup == null && nullToAbsent
          ? const Value.absent()
          : Value(partyGroup),
      phone: phone == null && nullToAbsent
          ? const Value.absent()
          : Value(phone),
      whatsapp: whatsapp == null && nullToAbsent
          ? const Value.absent()
          : Value(whatsapp),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      addressLine1: addressLine1 == null && nullToAbsent
          ? const Value.absent()
          : Value(addressLine1),
      addressLine2: addressLine2 == null && nullToAbsent
          ? const Value.absent()
          : Value(addressLine2),
      city: city == null && nullToAbsent ? const Value.absent() : Value(city),
      province: province == null && nullToAbsent
          ? const Value.absent()
          : Value(province),
      ntn: ntn == null && nullToAbsent ? const Value.absent() : Value(ntn),
      strn: strn == null && nullToAbsent ? const Value.absent() : Value(strn),
      cnic: cnic == null && nullToAbsent ? const Value.absent() : Value(cnic),
      buyerRegistrationType: Value(buyerRegistrationType),
      isOnAtl: isOnAtl == null && nullToAbsent
          ? const Value.absent()
          : Value(isOnAtl),
      openingBalancePaisa: Value(openingBalancePaisa),
      openingBalanceAsOfLocal: openingBalanceAsOfLocal == null && nullToAbsent
          ? const Value.absent()
          : Value(openingBalanceAsOfLocal),
      creditLimitPaisa: creditLimitPaisa == null && nullToAbsent
          ? const Value.absent()
          : Value(creditLimitPaisa),
      creditDays: creditDays == null && nullToAbsent
          ? const Value.absent()
          : Value(creditDays),
      defaultDiscountBp: Value(defaultDiscountBp),
      isActive: Value(isActive),
      priceTier: Value(priceTier),
    );
  }

  factory Party.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Party(
      id: serializer.fromJson<String>(json['id']),
      firmId: serializer.fromJson<String>(json['firm_id']),
      createdAtUtc: serializer.fromJson<int>(json['created_at_utc']),
      updatedAtUtc: serializer.fromJson<int>(json['updated_at_utc']),
      createdBy: serializer.fromJson<String>(json['created_by']),
      updatedBy: serializer.fromJson<String>(json['updated_by']),
      deletedAtUtc: serializer.fromJson<int?>(json['deleted_at_utc']),
