    required this.docDateLocal,
    this.partyId,
    this.partyNameSnapshot,
    this.partyNtnSnapshot,
    this.partyStrnSnapshot,
    this.partyAddressSnapshot,
    required this.status,
    required this.revision,
    this.supersedesId,
    this.voidedById,
    this.voidReason,
    required this.subtotalPaisa,
    required this.lineDiscountPaisa,
    required this.billDiscountPaisa,
    required this.taxablePaisa,
    required this.taxPaisa,
    required this.furtherTaxPaisa,
    required this.withholdingPaisa,
    required this.extraChargesPaisa,
    required this.roundOffPaisa,
    required this.totalPaisa,
    required this.paidPaisa,
    required this.balancePaisa,
    required this.costPaisa,
    required this.pricesIncludeTax,
    required this.roundingMode,
    required this.taxRuleVersion,
    this.placeOfSupply,
    this.saleType,
    this.salespersonId,
    this.notes,
    this.terms,
    this.vehicleNo,
    this.biltyNo,
    this.transporter,
    this.shipTo,
    this.supplierBillNo,
    required this.cashThresholdBreached,
    this.postedAtUtc,
  });
