    map['cost_paisa'] = Variable<int>(costPaisa);
    map['prices_include_tax'] = Variable<int>(pricesIncludeTax);
    map['rounding_mode'] = Variable<String>(roundingMode);
    map['tax_rule_version'] = Variable<String>(taxRuleVersion);
    if (!nullToAbsent || placeOfSupply != null) {
      map['place_of_supply'] = Variable<String>(placeOfSupply);
    }
    if (!nullToAbsent || saleType != null) {
      map['sale_type'] = Variable<String>(saleType);
    }
    if (!nullToAbsent || salespersonId != null) {
      map['salesperson_id'] = Variable<String>(salespersonId);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || terms != null) {
      map['terms'] = Variable<String>(terms);
    }
    if (!nullToAbsent || vehicleNo != null) {
      map['vehicle_no'] = Variable<String>(vehicleNo);
    }
    if (!nullToAbsent || biltyNo != null) {
      map['bilty_no'] = Variable<String>(biltyNo);
    }
    if (!nullToAbsent || transporter != null) {
