class Payment extends DataClass implements Insertable<Payment> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String paymentNo;
  final String direction;
  final String? partyId;
  final String paymentAccountId;
  final String mode;

  /// Whatever the shopkeeper wants to write down: a JazzCash TID, the last four
  /// of a card slip, nothing at all. We never verify it against anything,
  /// because there is nothing to verify it against.
  final String? reference;
  final int amountPaisa;

  /// Cash tender and change. Stored so a Z-report can reconcile the drawer.
  final int? tenderedPaisa;
  final int changePaisa;
  final int paymentDateUtc;
  final String paymentDateLocal;
  final String status;

  /// Post-dated cheques. The full lifecycle lands in M6; the columns exist now
  /// so a cheque taken in M3 is not lost data.
  final String? chequeNo;
  final int? chequeDateUtc;
  final String? chequeBank;
  final String? chequeStatus;
  final String? chequeImageAttachmentId;
  final String? notes;
  const Payment({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.paymentNo,
    required this.direction,
    this.partyId,
    required this.paymentAccountId,
    required this.mode,
    this.reference,
    required this.amountPaisa,
    this.tenderedPaisa,
    required this.changePaisa,
    required this.paymentDateUtc,
    required this.paymentDateLocal,
    required this.status,
    this.chequeNo,
    this.chequeDateUtc,
    this.chequeBank,
    this.chequeStatus,
    this.chequeImageAttachmentId,
    this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['payment_no'] = Variable<String>(paymentNo);
    map['direction'] = Variable<String>(direction);
    if (!nullToAbsent || partyId != null) {
      map['party_id'] = Variable<String>(partyId);
    }
    map['payment_account_id'] = Variable<String>(paymentAccountId);
    map['mode'] = Variable<String>(mode);
    if (!nullToAbsent || reference != null) {
      map['reference'] = Variable<String>(reference);
    }
    map['amount_paisa'] = Variable<int>(amountPaisa);
    if (!nullToAbsent || tenderedPaisa != null) {
      map['tendered_paisa'] = Variable<int>(tenderedPaisa);
    }
    map['change_paisa'] = Variable<int>(changePaisa);
    map['payment_date_utc'] = Variable<int>(paymentDateUtc);
    map['payment_date_local'] = Variable<String>(paymentDateLocal);
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || chequeNo != null) {
      map['cheque_no'] = Variable<String>(chequeNo);
    }
    if (!nullToAbsent || chequeDateUtc != null) {
      map['cheque_date_utc'] = Variable<int>(chequeDateUtc);
    }
    if (!nullToAbsent || chequeBank != null) {
      map['cheque_bank'] = Variable<String>(chequeBank);
    }
    if (!nullToAbsent || chequeStatus != null) {
      map['cheque_status'] = Variable<String>(chequeStatus);
    }
    if (!nullToAbsent || chequeImageAttachmentId != null) {
      map['cheque_image_attachment_id'] = Variable<String>(
        chequeImageAttachmentId,
      );
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    return map;
  }

  PaymentsCompanion toCompanion(bool nullToAbsent) {
    return PaymentsCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
          ? const Value.absent()
