          : Value(partyId),
      paymentAccountId: Value(paymentAccountId),
      mode: Value(mode),
      reference: reference == null && nullToAbsent
          ? const Value.absent()
          : Value(reference),
      amountPaisa: Value(amountPaisa),
      tenderedPaisa: tenderedPaisa == null && nullToAbsent
          ? const Value.absent()
          : Value(tenderedPaisa),
      changePaisa: Value(changePaisa),
      paymentDateUtc: Value(paymentDateUtc),
      paymentDateLocal: Value(paymentDateLocal),
      status: Value(status),
      chequeNo: chequeNo == null && nullToAbsent
          ? const Value.absent()
          : Value(chequeNo),
      chequeDateUtc: chequeDateUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(chequeDateUtc),
      chequeBank: chequeBank == null && nullToAbsent
          ? const Value.absent()
          : Value(chequeBank),
      chequeStatus: chequeStatus == null && nullToAbsent
          ? const Value.absent()
          : Value(chequeStatus),
      chequeImageAttachmentId: chequeImageAttachmentId == null && nullToAbsent
          ? const Value.absent()
          : Value(chequeImageAttachmentId),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
    );
  }

