          ..write('id: $id, ')
          ..write('firmId: $firmId, ')
          ..write('createdAtUtc: $createdAtUtc, ')
          ..write('updatedAtUtc: $updatedAtUtc, ')
          ..write('createdBy: $createdBy, ')
          ..write('updatedBy: $updatedBy, ')
          ..write('deletedAtUtc: $deletedAtUtc, ')
          ..write('originDeviceId: $originDeviceId, ')
          ..write('hlc: $hlc, ')
          ..write('rev: $rev, ')
          ..write('paymentNo: $paymentNo, ')
          ..write('direction: $direction, ')
          ..write('partyId: $partyId, ')
          ..write('paymentAccountId: $paymentAccountId, ')
          ..write('mode: $mode, ')
          ..write('reference: $reference, ')
          ..write('amountPaisa: $amountPaisa, ')
          ..write('tenderedPaisa: $tenderedPaisa, ')
          ..write('changePaisa: $changePaisa, ')
          ..write('paymentDateUtc: $paymentDateUtc, ')
          ..write('paymentDateLocal: $paymentDateLocal, ')
          ..write('status: $status, ')
          ..write('chequeNo: $chequeNo, ')
          ..write('chequeDateUtc: $chequeDateUtc, ')
          ..write('chequeBank: $chequeBank, ')
          ..write('chequeStatus: $chequeStatus, ')
          ..write('chequeImageAttachmentId: $chequeImageAttachmentId, ')
          ..write('notes: $notes, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

