class JournalEntry extends DataClass implements Insertable<JournalEntry> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String entryNo;
  final int entryDateUtc;
  final String entryDateLocal;
  final int fiscalYear;
  final String sourceType;
  final String? documentId;
  final String? paymentId;

  /// A correction never edits history; it posts the opposite entry and points
  /// at what it undid.
  final String? reversesEntryId;
  final String? narration;
  final int totalDebitPaisa;
  final int totalCreditPaisa;
  const JournalEntry({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.entryNo,
    required this.entryDateUtc,
    required this.entryDateLocal,
    required this.fiscalYear,
    required this.sourceType,
    this.documentId,
    this.paymentId,
    this.reversesEntryId,
    this.narration,
    required this.totalDebitPaisa,
    required this.totalCreditPaisa,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['entry_no'] = Variable<String>(entryNo);
    map['entry_date_utc'] = Variable<int>(entryDateUtc);
    map['entry_date_local'] = Variable<String>(entryDateLocal);
    map['fiscal_year'] = Variable<int>(fiscalYear);
    map['source_type'] = Variable<String>(sourceType);
    if (!nullToAbsent || documentId != null) {
      map['document_id'] = Variable<String>(documentId);
    }
    if (!nullToAbsent || paymentId != null) {
      map['payment_id'] = Variable<String>(paymentId);
    }
    if (!nullToAbsent || reversesEntryId != null) {
      map['reverses_entry_id'] = Variable<String>(reversesEntryId);
    }
    if (!nullToAbsent || narration != null) {
      map['narration'] = Variable<String>(narration);
    }
    map['total_debit_paisa'] = Variable<int>(totalDebitPaisa);
    map['total_credit_paisa'] = Variable<int>(totalCreditPaisa);
    return map;
  }

  JournalEntriesCompanion toCompanion(bool nullToAbsent) {
    return JournalEntriesCompanion(
      id: Value(id),
      firmId: Value(firmId),
      createdAtUtc: Value(createdAtUtc),
      updatedAtUtc: Value(updatedAtUtc),
      createdBy: Value(createdBy),
      updatedBy: Value(updatedBy),
      deletedAtUtc: deletedAtUtc == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAtUtc),
      originDeviceId: Value(originDeviceId),
      hlc: Value(hlc),
      rev: Value(rev),
      entryNo: Value(entryNo),
      entryDateUtc: Value(entryDateUtc),
      entryDateLocal: Value(entryDateLocal),
      fiscalYear: Value(fiscalYear),
      sourceType: Value(sourceType),
      documentId: documentId == null && nullToAbsent
          ? const Value.absent()
          : Value(documentId),
      paymentId: paymentId == null && nullToAbsent
          ? const Value.absent()
          : Value(paymentId),
      reversesEntryId: reversesEntryId == null && nullToAbsent
          ? const Value.absent()
          : Value(reversesEntryId),
      narration: narration == null && nullToAbsent
          ? const Value.absent()
          : Value(narration),
      totalDebitPaisa: Value(totalDebitPaisa),
      totalCreditPaisa: Value(totalCreditPaisa),
    );
  }

