      rev: serializer.fromJson<int>(json['rev']),
      entryNo: serializer.fromJson<String>(json['entry_no']),
      entryDateUtc: serializer.fromJson<int>(json['entry_date_utc']),
      entryDateLocal: serializer.fromJson<String>(json['entry_date_local']),
      fiscalYear: serializer.fromJson<int>(json['fiscal_year']),
      sourceType: serializer.fromJson<String>(json['source_type']),
      documentId: serializer.fromJson<String?>(json['document_id']),
