class StockLot extends DataClass implements Insertable<StockLot> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String itemId;
  final String lotNo;
  final String? batchNo;
  final String? mfgDateLocal;
  final String? expiryDateLocal;

  /// MRP HANGS OFF THE BATCH, NOT THE ITEM. The Drug Pricing Policy fixes the
  /// maximum retail price per batch: a price increase does not apply to stock
  /// manufactured before it, so two batches of the same medicine on the same
  /// shelf legally sell at different prices. No app built for another market
  /// has a reason to model this.
  final int? mrpPaisa;
  final int costMilliPaisa;

  /// DRAP MIS/GL/T&T/001 s.14.2.2 requires retailers to be able to scan AIDC
  /// data from 9 October 2026. One GS1 DataMatrix carries (01) GTIN,
  /// (17) expiry, (10) batch and (21) serial; a single scan fills this row.
  final String? gtin;
  final String? serial;
  final int? receivedAtUtc;
  final String? supplierPartyId;
  const StockLot({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.itemId,
    required this.lotNo,
    this.batchNo,
    this.mfgDateLocal,
    this.expiryDateLocal,
    this.mrpPaisa,
    required this.costMilliPaisa,
    this.gtin,
    this.serial,
    this.receivedAtUtc,
    this.supplierPartyId,
  });
