      map['mrp_paisa'] = Variable<int>(mrpPaisa);
    }
    map['cost_milli_paisa'] = Variable<int>(costMilliPaisa);
    if (!nullToAbsent || gtin != null) {
      map['gtin'] = Variable<String>(gtin);
    }
    if (!nullToAbsent || serial != null) {
      map['serial'] = Variable<String>(serial);
    }
    if (!nullToAbsent || receivedAtUtc != null) {
