class DocumentLine extends DataClass implements Insertable<DocumentLine> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String documentId;
  final int lineNo;
  final String? itemId;

  /// Snapshots again. An item renamed or repriced next month does not rewrite
  /// history, and a deleted item does not blank out an old invoice.
  final String itemNameSnapshot;
  final String? itemCodeSnapshot;
  final String? hsCodeSnapshot;
  final String? description;

  /// What the cashier typed, in the unit they typed it in.
  final int qtyThousandths;
  final String? unitId;
  final String unitCodeSnapshot;

  /// The same quantity in the item's base unit. Stock moves on this.
  final int baseQtyThousandths;

  /// Milli-paisa per the unit above.
  final int rateMilliPaisa;
  final int? mrpPaisa;
  final String? lotId;
  final int grossPaisa;

  /// Basis points, so 100% is 10000. Nothing else is a discount: a line
  /// discount over the line is a refund, and a negative one is a surcharge
  /// pretending otherwise.
  final int discountBp;
  final int discountPaisa;
  final int taxablePaisa;
  final int taxPaisa;
  final int lineTotalPaisa;

  /// Cost of goods on this line, captured at post time from the weighted
  /// average. Bill-wise profit reads this, never a recomputation against
  /// today's cost.
  final int costPaisa;
  final int isFreeItem;
  const DocumentLine({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.documentId,
    required this.lineNo,
    this.itemId,
    required this.itemNameSnapshot,
    this.itemCodeSnapshot,
    this.hsCodeSnapshot,
    this.description,
    required this.qtyThousandths,
    this.unitId,
    required this.unitCodeSnapshot,
    required this.baseQtyThousandths,
    required this.rateMilliPaisa,
    this.mrpPaisa,
    this.lotId,
    required this.grossPaisa,
    required this.discountBp,
    required this.discountPaisa,
    required this.taxablePaisa,
    required this.taxPaisa,
    required this.lineTotalPaisa,
    required this.costPaisa,
    required this.isFreeItem,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['document_id'] = Variable<String>(documentId);
    map['line_no'] = Variable<int>(lineNo);
    if (!nullToAbsent || itemId != null) {
      map['item_id'] = Variable<String>(itemId);
    }
    map['item_name_snapshot'] = Variable<String>(itemNameSnapshot);
    if (!nullToAbsent || itemCodeSnapshot != null) {
      map['item_code_snapshot'] = Variable<String>(itemCodeSnapshot);
    }
    if (!nullToAbsent || hsCodeSnapshot != null) {
      map['hs_code_snapshot'] = Variable<String>(hsCodeSnapshot);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    map['qty_thousandths'] = Variable<int>(qtyThousandths);
    if (!nullToAbsent || unitId != null) {
      map['unit_id'] = Variable<String>(unitId);
    }
    map['unit_code_snapshot'] = Variable<String>(unitCodeSnapshot);
    map['base_qty_thousandths'] = Variable<int>(baseQtyThousandths);
    map['rate_milli_paisa'] = Variable<int>(rateMilliPaisa);
    if (!nullToAbsent || mrpPaisa != null) {
      map['mrp_paisa'] = Variable<int>(mrpPaisa);
    }
    if (!nullToAbsent || lotId != null) {
      map['lot_id'] = Variable<String>(lotId);
    }
    map['gross_paisa'] = Variable<int>(grossPaisa);
    map['discount_bp'] = Variable<int>(discountBp);
    map['discount_paisa'] = Variable<int>(discountPaisa);
    map['taxable_paisa'] = Variable<int>(taxablePaisa);
    map['tax_paisa'] = Variable<int>(taxPaisa);
    map['line_total_paisa'] = Variable<int>(lineTotalPaisa);
    map['cost_paisa'] = Variable<int>(costPaisa);
    map['is_free_item'] = Variable<int>(isFreeItem);
    return map;
  }

  DocumentLinesCompanion toCompanion(bool nullToAbsent) {
    return DocumentLinesCompanion(
      id: Value(id),
      firmId: Value(firmId),
