      occurredAtUtc: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}occurred_at_utc'],
      )!,
      occurredOnLocal: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}occurred_on_local'],
      )!,
      reason: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}reason'],
      ),
    );
  }

  @override
  StockLedger createAlias(String alias) {
    return StockLedger(attachedDatabase, alias);
  }

  @override
  bool get isStrict => true;
  @override
  bool get dontWriteConstraints => true;
}

class StockLedgerData extends DataClass implements Insertable<StockLedgerData> {
  final String id;
  final String firmId;
  final int createdAtUtc;
  final int updatedAtUtc;
  final String createdBy;
  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String itemId;

  /// Reserved dimension. Named `location_code` rather than `location_id`
  /// deliberately: there is no `locations` table until M11, and a column
  /// called `*_id` with no REFERENCES clause is exactly the lie this schema
  /// exists to prevent. The ledger is already partitioned by location, so M11
  /// adds a parent table and a lookup — it never recomputes a balance.
  final String locationCode;
  final String? lotId;
  final String? documentId;
  final String? documentLineId;
  final String txnType;

  /// Always in the item's BASE unit, thousandths. Negative is stock leaving.
  final int qtyDeltaThousandths;
  final int rateMilliPaisa;
  final int valueDeltaPaisa;

  /// Cached running balance. Derived, verified, never authoritative.
  final int? balanceAfterThousandths;
  final int occurredAtUtc;
  final String occurredOnLocal;
  final String? reason;
  const StockLedgerData({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
    required this.createdBy,
    required this.updatedBy,
    this.deletedAtUtc,
    required this.originDeviceId,
    required this.hlc,
    required this.rev,
    required this.itemId,
    required this.locationCode,
    this.lotId,
    this.documentId,
    this.documentLineId,
    required this.txnType,
    required this.qtyDeltaThousandths,
    required this.rateMilliPaisa,
    required this.valueDeltaPaisa,
    this.balanceAfterThousandths,
    required this.occurredAtUtc,
    required this.occurredOnLocal,
    this.reason,
  });
