  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['created_at_utc'] = Variable<int>(createdAtUtc);
    map['updated_at_utc'] = Variable<int>(updatedAtUtc);
    map['created_by'] = Variable<String>(createdBy);
    map['updated_by'] = Variable<String>(updatedBy);
    if (!nullToAbsent || deletedAtUtc != null) {
      map['deleted_at_utc'] = Variable<int>(deletedAtUtc);
    }
    map['origin_device_id'] = Variable<String>(originDeviceId);
    map['hlc'] = Variable<String>(hlc);
    map['rev'] = Variable<int>(rev);
    map['item_id'] = Variable<String>(itemId);
    map['location_code'] = Variable<String>(locationCode);
    if (!nullToAbsent || lotId != null) {
      map['lot_id'] = Variable<String>(lotId);
    }
    if (!nullToAbsent || documentId != null) {
      map['document_id'] = Variable<String>(documentId);
    }
    if (!nullToAbsent || documentLineId != null) {
      map['document_line_id'] = Variable<String>(documentLineId);
    }
    map['txn_type'] = Variable<String>(txnType);
    map['qty_delta_thousandths'] = Variable<int>(qtyDeltaThousandths);
    map['rate_milli_paisa'] = Variable<int>(rateMilliPaisa);
    map['value_delta_paisa'] = Variable<int>(valueDeltaPaisa);
    if (!nullToAbsent || balanceAfterThousandths != null) {
      map['balance_after_thousandths'] = Variable<int>(balanceAfterThousandths);
    }
    map['occurred_at_utc'] = Variable<int>(occurredAtUtc);
    map['occurred_on_local'] = Variable<String>(occurredOnLocal);
    if (!nullToAbsent || reason != null) {
      map['reason'] = Variable<String>(reason);
    }
    return map;
  }

