  final String updatedBy;
  final int? deletedAtUtc;
  final String originDeviceId;
  final String hlc;
  final int rev;
  final String docType;
  final String deviceId;

  /// 2627 means FY 2026-27.
  final int fiscalYear;
  final String prefix;
  final int padWidth;
  final int nextValue;

  /// Reserved block per counter, so a LAN-synced second till cannot collide.
  final int blockStart;
  final int blockEnd;
  const NumberingSequence({
    required this.id,
    required this.firmId,
    required this.createdAtUtc,
    required this.updatedAtUtc,
